/**
 * Main App Component - Router and navigation
 */

import React, { useState } from 'react';
import Upload from './components/Upload';
import Dashboard from './components/Dashboard';
import Prediction from './components/Prediction';
import Simulation from './components/Simulation';
import FeaturesShowcase from './components/FeaturesShowcase';
import './App.css';

function App() {
  const [currentPage, setCurrentPage] = useState('upload');
  const [analysisResults, setAnalysisResults] = useState(null);
  const [logs, setLogs] = useState([]);

  const handleAnalysisStart = () => {
    console.log('Analysis started...');
  };

  const handleAnalysisComplete = (results) => {
    setAnalysisResults(results);
    setLogs(results.logs || []);
    setCurrentPage('dashboard');
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100">
      {/* Navigation */}
      <nav className="bg-white shadow-md">
        <div className="max-w-7xl mx-auto px-4 py-4">
          <div className="flex items-center justify-between">
            <div className="text-2xl font-bold text-blue-600">
              🔷 Multi-Agent AI System
            </div>
            <div className="flex gap-4">
              <button
                onClick={() => setCurrentPage('upload')}
                className={`px-4 py-2 rounded-lg font-semibold transition ${
                  currentPage === 'upload'
                    ? 'bg-blue-600 text-white'
                    : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                }`}
              >
                📁 Upload
              </button>
              {analysisResults && (
                <button
                  onClick={() => setCurrentPage('showcase')}
                  className={`px-4 py-2 rounded-lg font-semibold transition ${
                    currentPage === 'showcase'
                      ? 'bg-blue-600 text-white'
                      : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                  }`}
                >
                  🚀 Showcase
                </button>
              )}
              {analysisResults && (
                <>
                  <button
                    onClick={() => setCurrentPage('dashboard')}
                    className={`px-4 py-2 rounded-lg font-semibold transition ${
                      currentPage === 'dashboard'
                        ? 'bg-blue-600 text-white'
                        : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                    }`}
                  >
                    📊 Dashboard
                  </button>
                  <button
                    onClick={() => setCurrentPage('prediction')}
                    className={`px-4 py-2 rounded-lg font-semibold transition ${
                      currentPage === 'prediction'
                        ? 'bg-blue-600 text-white'
                        : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                    }`}
                  >
                    🔮 Predict
                  </button>
                  <button
                    onClick={() => setCurrentPage('simulation')}
                    className={`px-4 py-2 rounded-lg font-semibold transition ${
                      currentPage === 'simulation'
                        ? 'bg-blue-600 text-white'
                        : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                    }`}
                  >
                    🎮 Simulate
                  </button>
                </>
              )}
            </div>
          </div>
        </div>
      </nav>

      {/* Page Content */}
      <main className="py-8">
        {currentPage === 'upload' && (
          <Upload
            onAnalysisStart={handleAnalysisStart}
            onAnalysisComplete={handleAnalysisComplete}
          />
        )}
        {currentPage === 'dashboard' && analysisResults && (
          <Dashboard results={analysisResults} logs={logs} />
        )}
        {currentPage === 'prediction' && analysisResults && <Prediction />}
        {currentPage === 'simulation' && analysisResults && <Simulation />}
        {currentPage === 'showcase' && analysisResults && (
          <FeaturesShowcase results={analysisResults} logs={logs} />
        )}
        {currentPage === 'showcase' && !analysisResults && <FeaturesShowcase />}
      </main>

      {/* Footer */}
      <footer className="bg-gray-800 text-white text-center py-6 mt-12">
        <div className="max-w-7xl mx-auto">
          <p>
            Goal-Driven Autonomous Multi-Agent Intelligence System v1.0
          </p>
          <p className="text-sm text-gray-400 mt-2">
            Built with Python, FastAPI, React & LangChain
          </p>
        </div>
      </footer>
    </div>
  );
}

export default App;
